CREATE OR REPLACE FUNCTION public.enforce_review_truth()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_validation_status text;
  v_validation_resolution uuid;
begin
  select status, resolution_record_id
  into v_validation_status, v_validation_resolution
  from public.validation_results
  where id = new.validation_result_id;

  if v_validation_resolution is null then
    raise exception 'Review Truth violation: validation result does not exist';
  end if;

  if v_validation_resolution <> new.resolution_record_id then
    raise exception 'Review Truth violation: validation result belongs to another resolution';
  end if;

  if new.review_status = 'approved' and v_validation_status <> 'passed' then
    raise exception 'Review Truth violation: approval requires passed validation';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_review_decision_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_session public.review_sessions%rowtype;
  v_required int;
  v_checked int;
  v_failed int;
  v_expected_reviewer text;
begin
  select * into v_session from public.review_sessions where id = new.review_session_id;
  if not found then raise exception 'Review session not found'; end if;

  select count(*) into v_required
  from public.review_criteria c
  where c.structure_id = v_session.structure_id and c.required = true;

  select count(*) into v_checked
  from public.review_criterion_results r
  join public.review_criteria c on c.id = r.criterion_id
  where r.review_session_id = new.review_session_id and c.required = true;

  select count(*) into v_failed
  from public.review_criterion_results r
  join public.review_criteria c on c.id = r.criterion_id
  where r.review_session_id = new.review_session_id and c.required = true and r.passed = false;

  select required_reviewer_type into v_expected_reviewer from public.review_rules where id = v_session.rule_id;

  if new.reviewer_type <> v_expected_reviewer then
    raise exception 'Reviewer type % does not satisfy required reviewer type %', new.reviewer_type, v_expected_reviewer;
  end if;

  if v_checked < v_required then
    raise exception 'Cannot decide review: required criteria incomplete (% of % checked)', v_checked, v_required;
  end if;

  if new.decision = 'approved' and v_failed > 0 then
    raise exception 'Cannot approve review: one or more required criteria failed';
  end if;

  update public.review_sessions
  set status = new.decision,
      completed_at = case when new.final then now() else completed_at end
  where id = new.review_session_id;

  return new;
end $function$

CREATE OR REPLACE FUNCTION public.bridge_lock_decision_basis()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_record uuid;
begin
  case tg_table_name
    when 'conversion_candidates' then
      v_record := new.record_id;
    when 'validation_results' then
      select record_id into v_record from public.conflicts where id = new.conflict_id;
    when 'review_sessions' then
      select c.record_id into v_record from public.review_records r
        join public.resolution_records rr on rr.id = r.resolution_record_id
        join public.conflicts c on c.id = rr.conflict_id where r.id = new.review_record_id;
    when 'review_decisions' then
      select c.record_id into v_record from public.review_sessions s
        join public.review_records r on r.id = s.review_record_id
        join public.resolution_records rr on rr.id = r.resolution_record_id
        join public.conflicts c on c.id = rr.conflict_id where s.id = new.review_session_id;
  end case;
  if v_record is null then raise sqlstate 'PT409' using message = 'Decision basis has no case reference'; end if;
  perform 1 from public.records where id = v_record for update;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.bridge_trace_review_session()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_validation public.validation_results%rowtype;
begin
  if new.validation_result_id is not null then
    select * into v_validation from public.validation_results where id = new.validation_result_id;
  end if;

  new.correlation_id := coalesce(new.correlation_id, v_validation.correlation_id, gen_random_uuid());
  new.trace_id := coalesce(new.trace_id, v_validation.trace_id, gen_random_uuid());
  new.span_id := coalesce(new.span_id, gen_random_uuid());

  if v_validation.id is not null then
    new.parent_span_id := coalesce(new.parent_span_id, v_validation.span_id);
    new.causation_id := coalesce(new.causation_id, v_validation.span_id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.bridge_guard_review_claim_freshness()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_record uuid; v_claims_basis text;
begin
  if lower(coalesce(new.decision, '')) <> 'approved' then return new; end if;
  select c.record_id into v_record
  from public.review_sessions s
  join public.review_records r on r.id = s.review_record_id
  join public.resolution_records rr on rr.id = r.resolution_record_id
  join public.conflicts c on c.id = rr.conflict_id
  where s.id = new.review_session_id;
  if v_record is null or new.validation_result_id is null then
    raise sqlstate 'PT409' using message = 'Review lacks a case or validation basis';
  end if;
  perform 1 from public.records where id = v_record for update;
  if public.bridge_claims_after_validation(v_record, new.validation_result_id) then
    raise sqlstate 'PT409' using message = 'An active claim was created after this validation; create a new validation and review';
  end if;
  v_claims_basis := public.bridge_claims_basis(v_record);
  if not coalesce(new.evidence_refs @> array['claims:' || v_claims_basis], false) then
    raise sqlstate 'PT409' using message = 'Claims changed before review approval; reload the case';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.bridge_guard_unresolved_semantic_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_record uuid;
begin
  if lower(coalesce(new.decision, '')) <> 'approved' then return new; end if;
  select c.record_id into v_record
  from public.review_sessions s
  join public.review_records r on r.id = s.review_record_id
  join public.resolution_records rr on rr.id = r.resolution_record_id
  join public.conflicts c on c.id = rr.conflict_id
  where s.id = new.review_session_id;
  if v_record is null then
    raise sqlstate 'PT409' using message = 'Review lacks a case';
  end if;
  perform 1 from public.records where id = v_record for update;
  if public.bridge_has_unresolved_semantic_claim(v_record) then
    raise sqlstate 'PT409' using message = 'An unresolved semantic mapping claim blocks review and release';
  end if;
  return new;
end;
$function$
